def test_padding_no_size():
    config = Config()
    root = Node(config)
    root.position_type = PositionType.ABSOLUTE
    root.set_padding(Edge.LEFT, 10)
    root.set_padding(Edge.TOP, 10)
    root.set_padding(Edge.RIGHT, 10)
    root.set_padding(Edge.BOTTOM, 10)
    root.calculate_layout(None, None, Direction.LTR)
    assert root.layout.left == pytest.approx(0, abs=1e-4)
    assert root.layout.top == pytest.approx(0, abs=1e-4)
    assert root.layout.width == pytest.approx(20, abs=1e-4)
    assert root.layout.height == pytest.approx(20, abs=1e-4)
    root.calculate_layout(None, None, Direction.RTL)
    assert root.layout.left == pytest.approx(0, abs=1e-4)
    assert root.layout.top == pytest.approx(0, abs=1e-4)
    assert root.layout.width == pytest.approx(20, abs=1e-4)
    assert root.layout.height == pytest.approx(20, abs=1e-4)


